import path from "node:path";
import { drizzle } from "drizzle-orm/postgres-js";
import { migrate } from "drizzle-orm/postgres-js/migrator";
import postgres from "postgres";
import type { Env } from "@/lib/env";
import { logger } from "@/lib/log";

const mlog = logger("migrate");

// Arbitrary constant: the advisory lock id shared by every worker of this app.
const LOCK_ID = 727_001;

/**
 * Applies pending migrations from ./drizzle (generated by `npm run db:generate`; the same
 * files and journal `drizzle-kit migrate` uses). One dedicated connection holds a
 * Postgres advisory lock, so concurrent worker starts migrate one at a time.
 */
export async function runMigrations(env: Env): Promise<void> {
  const url = env.DATABASE_URL_UNPOOLED ?? env.DATABASE_URL;
  if (new URL(url).hostname.includes("-pooler")) {
    mlog.warn("migrating through a pooled Neon URL; set DATABASE_URL_UNPOOLED to the direct URL");
  }
  const sql = postgres(url, { max: 1, prepare: false, onnotice: () => {} });
  try {
    await sql`select pg_advisory_lock(${LOCK_ID})`;
    const started = Date.now();
    await migrate(drizzle(sql), { migrationsFolder: path.join(process.cwd(), "drizzle") });
    mlog.info({ ms: Date.now() - started }, "migrations up to date");
  } finally {
    await sql`select pg_advisory_unlock(${LOCK_ID})`.catch(() => {});
    await sql.end({ timeout: 5 });
  }
}
